import{_ as n,o as i,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.4.4 View Agency Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-4-view-agency-profile/spec.md","filePath":"feature/agency-workspace/3-4-4-view-agency-profile/spec.md"}'),t={name:"feature/agency-workspace/3-4-4-view-agency-profile/spec.md"};function r(s,e,l,c,d,h){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-4-4-view-agency-profile" tabindex="-1">3.4.4 View Agency Profile <a class="header-anchor" href="#_3-4-4-view-agency-profile" aria-label="Permalink to &quot;3.4.4 View Agency Profile&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>A signed-in user opens the profile of an Agency they belong to — either as its Owner or as one of its Members. The profile is also shown straight after selecting an Agency from the Agency list (3.4.1).</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency Owner or Agency Member (any member role).</li><li><strong>Purpose:</strong> Show the branding and company information of an Agency to the people who work in it, so they know which company they represent.</li><li><strong>Interface:</strong> Agency Profile page (<code>/agencies/:agencyId/profile</code>) — the branding section of the Agency with name, logo, description, category, company size, contact details, brand colour, logo icon, tagline, founded year and the social links. There is no separate profile data source; the page reads the same Agency profile used elsewhere.</li><li><strong>Data Processing:</strong> The system loads the Agency by its identifier and then checks the caller: the caller must be the Owner of that Agency or hold an Agency Member record in it. When the caller is neither, the request is refused. The system then returns the branding and company information of the Agency.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Agency Profile page:</p><ul><li>Header with name, logo, tagline and brand colour.</li><li>Company information: description, category, company size, website, phone, location, founded year (rendered as years in business, counted from the current year).</li><li>Social links: Facebook, LinkedIn, Instagram.</li><li>No Workspace list and no Member list are shown here — this screen carries company information only.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Agency identifier (<code>agencyId</code>) and a signed-in session.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> Agency profile — name, logoUrl, description, category (AgencyCategory), companySize (CompanySize), website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, plus id, ownerId, status (EntityStatus: ACTIVE / SOFT_DELETED), createdAt and updatedAt (full field list at 3.4.1). The Agency Member records of the caller are used for the access check.</li><li><strong>Output:</strong> The profile of the Agency, restricted to branding and company information. No internal data such as Workspace or Member lists is returned.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29 (analogous):</strong> Multi-tenancy — only the Owner of the Agency, or a user holding an Agency Member record in it, may view the profile, mirroring the workspace-scoped access rule (BR-29). Any other signed-in user is refused with <code>400 NOT_AGENCY_MEMBER</code>.</li><li>The Owner always has access, even when no Agency Member record exists for them; the Owner check stands on its own.</li><li>Every member role may view the profile — role does not narrow access.</li><li>The profile is not public. A user must be signed in and belong to the Agency; an outside party cannot preview an Agency profile.</li><li>This screen differs from the Agency Dashboard (3.4.2): the profile carries branding and company information, while the dashboard carries management figures.</li><li>The profile response holds no internal detail beyond branding and company information.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>No signed-in session, or an invalid one → <code>401 UNAUTHORIZED</code>, refused before the Agency logic runs.</li><li>Agency does not exist → Display: MSG38</li><li>Caller is neither the Owner nor a Member of the Agency → Display: MSG39</li><li>Agency already soft-deleted → the record is still returned, so the Owner and Members can still view the profile. See 3.4.6 for the removal behaviour.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user opens the profile of an Agency.</li><li>The client requests the Agency profile with the signed-in session.</li><li>The system confirms the session, then loads the Agency by its identifier.</li><li>The system confirms that the caller is the Owner of the Agency or holds an Agency Member record in it.</li><li>The system returns the branding and company information of the Agency.</li><li>The client renders the profile, including the years in business counted from the founded year.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: No signed-in session, or an invalid one → <code>401 UNAUTHORIZED</code>, toast MSG22. 2.a2: The user signs in again and retries.</li><li>3.a1: Agency does not exist → <code>404 AGENCY_NOT_FOUND</code>, toast MSG38. 3.a2: The user returns to the Agency list.</li><li>4.a1: Caller belongs to no part of the Agency → <code>400 NOT_AGENCY_MEMBER</code>, toast MSG39; no profile data returned. 4.a2: The user returns to the Agency list and opens an Agency they belong to.</li><li>4.b1: Agency already soft-deleted → the profile is still returned to the Owner and Members; no error, no toast. 4.b2: Removal does not revoke viewing at this point; the user continues viewing normally.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>No Agency data is created, changed or removed.</li><li>The profile shows correct company information and exposes no internal information.</li></ul>',22)])])}const f=n(t,[["render",r]]);export{g as __pageData,f as default};
